#define SAMPLE_T 8.
#define SAMPLE_W 8.
const float PI = 3.14159265358979323846;

// https://www.pcg-random.org/
uint pcg(uint v)
{
	uint state = v * 747796405u + 2891336453u;
	uint word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
	return (word >> 22u) ^ word;
}
// http://www.jcgt.org/published/0009/03/02/
uvec3 pcg3d(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;
    v ^= v >> 16u;
    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;
    return v;
}

// algorithm to construct an orthonormal basis including `n`
// see https://sci-hub.se/10.1016/j.cad.2012.11.003 table A.1
mat3x3 hh(vec3 n)
{
    if (n.x >= 0.) {
        return mat3x3(
            n,
            vec3(-n.y, 1. - n.y * n.y / (n.x + 1.), -n.y * n.z / (n.x + 1.)),
            vec3(-n.z, -n.y * n.z / (n.x + 1.), 1. - n.z * n.z / (n.x + 1.))
        );
    } else {
        return mat3x3(
            n,
            vec3(n.z, n.y * n.z / (n.x - 1.), 1. + n.z * n.z / (n.x - 1.)),
            vec3(n.y, 1. + n.y * n.y / (n.x - 1.), n.y * n.z / (n.x - 1.))
        );
    }
}

vec4 hypercubeInterval(vec4 center, mat4x4 orient_inv, vec3 ro, vec3 rd)
{
    mat4x4 worldFromRd = mat4x4(hh(rd));
    mat4x4 objectFromWorld = orient_inv;
    mat4x4 rdFromObject = inverse(objectFromWorld * worldFromRd);
    vec4 c1 = rdFromObject * vec4(1, 1, 1, 1);
    vec4 c2 = rdFromObject * vec4(1, 1, 1, -1);
    vec4 c3 = rdFromObject * vec4(1, 1, -1, 1);
    vec4 c4 = rdFromObject * vec4(1, 1, -1, -1);
    vec4 c5 = rdFromObject * vec4(1, -1, 1, 1);
    vec4 c6 = rdFromObject * vec4(1, -1, 1, -1);
    vec4 c7 = rdFromObject * vec4(1, -1, -1, 1);
    vec4 c8 = rdFromObject * vec4(1, -1, -1, -1);
    vec2 h = max(
        max(
            max(abs(c1.xw), abs(c2.xw)),
            max(abs(c3.xw), abs(c4.xw))
        ),
        max(
            max(abs(c5.xw), abs(c6.xw)),
            max(abs(c7.xw), abs(c8.xw))
        )
    );
    vec3 oc = ro - center.xyz;
    float b = dot( oc, rd );
    h.y = min(h.y, 0.5);
    return vec4( -b-h.x, -b+h.x, center.w-h.y, center.w+h.y);
}

bool hypercubeInside2(vec4 d, float woff, mat4x4 orient_inv)
{
    d.w = fract(d.w + 0.5) - 0.5 + woff;
    d = orient_inv * d;
    return
        (d.x >= -1. && d.x <= 1. &&
        d.y >= -1. && d.y <= 1. &&
        d.z >= -1. && d.z <= 1. &&
        d.w >= -1. && d.w <= 1.)
        #if 0
        &&!(
        (d.x >= -0.85 && d.x <= 0.85 && d.y >= -0.85 && d.y <= 0.85) ||
        (d.x >= -0.85 && d.x <= 0.85 && d.z >= -0.85 && d.z <= 0.85) ||
        (d.x >= -0.85 && d.x <= 0.85 && d.w >= -0.85 && d.w <= 0.85) ||
        (d.y >= -0.85 && d.y <= 0.85 && d.z >= -0.85 && d.z <= 0.85) ||
        (d.y >= -0.85 && d.y <= 0.85 && d.w >= -0.85 && d.w <= 0.85) ||
        (d.z >= -0.85 && d.z <= 0.85 && d.w >= -0.85 && d.w <= 0.85))
        #endif
        ;
}

bool hypercubeInside(vec4 center, mat4x4 orient_inv, vec4 coordinate)
{
    vec4 d = coordinate - center;
    if (hypercubeInside2(d, 0., orient_inv))
        return true;
    if (hypercubeInside2(d, 1., orient_inv))
        return true;
    if (hypercubeInside2(d, -1., orient_inv))
        return true;
    return false;
}

float to01(uint u)
{
    return float(u) / float(0xffffffffu);
}

// from https://www.shadertoy.com/view/MXXXRS
vec3 lch2rgb(vec3 lch) {
    lch.y *= 0.33;

    vec3 lab = vec3(
        lch.x,
        lch.y * cos(lch.z * PI*2.0),
        lch.y * sin(lch.z * PI*2.0)
    );

    vec3 lms = vec3(
        lab.x + 0.3963377774f * lab.y + 0.2158037573f * lab.z,
        lab.x - 0.1055613458f * lab.y - 0.0638541728f * lab.z,
        lab.x - 0.0894841775f * lab.y - 1.2914855480f * lab.z
    );

    lms = pow(max(lms, vec3(0.0)), vec3(3.0));

    vec3 rgb = vec3(
        +4.0767416621f * lms.x - 3.3077115913f * lms.y + 0.2309699292f * lms.z,
        -1.2684380046f * lms.x + 2.6097574011f * lms.y - 0.3413193965f * lms.z,
        -0.0041960863f * lms.x - 0.7034186147f * lms.y + 1.7076147010f * lms.z
    );

    return rgb;
}
vec3 colorForW(float w)
{
    return lch2rgb(vec3(1, 1, w));
}
void hypercube(vec4 center, mat4x4 orient, vec3 eye, vec3 dir, uint rng, inout vec3 s)
{
    vec4 iv = hypercubeInterval(center, orient, eye, dir);
    float dt = iv.y - iv.x;
    float dw = iv.w - iv.z;
    if (dt > 0. && dw > 0.) {
        for (float st = 0.; st < SAMPLE_T; st += 1.) {
            float as = dt * dw / (SAMPLE_T * SAMPLE_W);
            for (float sw = 0.; sw < SAMPLE_W; sw += 1.) {
                uvec3 subrng = pcg3d(uvec3(rng, st, sw));
                float t = dt * (st + to01(subrng.x)) / SAMPLE_T + iv.x;
                float w = dw * (sw + to01(subrng.y)) / SAMPLE_W + iv.z;
                vec3 p3 = eye + dir * t;
                vec4 p = vec4(p3, w);
                if (hypercubeInside(center, orient, p)) {
                    s += colorForW(w) * as;
                }
            }
        }
    }
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    uvec3 rng = pcg3d(uvec3(fragCoord, iTime * 1000.));
    vec2 uv = 2. * fragCoord/iResolution.xy - 1.;
    uv.x *= iResolution.x / iResolution.y;

    vec3 eye = vec3(0, 0, -2);
    vec3 imagePlaneCenter = vec3(0, 0, -1);
    vec3 imagePlaneU = vec3(0.35, 0, 0);
    vec3 imagePlaneV = vec3(0, 0.35, 0);
    vec3 dir = normalize(imagePlaneCenter + imagePlaneU * uv.x + imagePlaneV * uv.y - eye);

    vec3 s = vec3(0);

    float rots = sin(iTime * PI * 3. / 10.);
    float rotc = cos(iTime * PI * 3. / 10.);
    float rots2 = sin(iTime * PI * 2.5 / 10.);
    float rotc2 = cos(iTime * PI * 2.5 / 10.);
    float rots3 = sin(iTime * PI * 1. / 10.);
    float rotc3 = cos(iTime * PI * 1. / 10.);
    mat4x4 orient = mat4x4(0.5);
    orient *= mat4x4(
        1, 0, 0, 0,
        0, rotc, 0, -rots,
        0, 0, 1, 0,
        0, rots, 0, rotc
    );
    orient *= mat4x4(
        rotc2, 0, 0, -rots2,
        0, 1, 0, 0,
        0, 0, 1, 0,
        rots2, 0, 0, rotc2
    );
    orient *= mat4x4(
        rotc3, 0, rots3, 0,
        0, 1, 0, 0,
        -rots3, 0, rotc3, 0,
        0, 0, 0, 1
    );
    hypercube(vec4(0, 0, 1, 0.4), inverse(orient), eye, dir, rng.z, s);
    fragColor = vec4(pow(s, vec3(0.5)), 1);
}
